const BROKER_ROLES: readonly DevReviewRole[] = BROKER_AGENT_ROLES;
const BROKER_LANGUAGE_KEY = 'octo-broker-language';
const BROKER_REVIEW_MODE_KEY = 'octo-broker-review-mode';
const BROKER_BROWSER_REVIEW_KEY = 'octo-broker-browser-review';
const BROKER_CONTINUOUS_KEY = 'octo-broker-continuous';
// Continuous sub-mode: 'auto' = agent decides the next unit; 'queue' = feed user-provided tasks.
const BROKER_CONTINUOUS_MODE_KEY = 'octo-broker-continuous-mode';
const BROKER_TASK_QUEUE_KEY = 'octo-broker-task-queue';

const normalizeBrokerContinuousMode = (value: string | null | undefined): 'auto' | 'queue' => {
  return String(value || '').trim().toLowerCase() === 'queue' ? 'queue' : 'auto';
};
// Push-on-merge defaults ON (preserves prior behavior), but is now an explicit toggle. When
// off, APPROVED merges LOCALLY only and never touches the remote.
const BROKER_PUSH_ON_MERGE_KEY = 'octo-broker-push-on-merge';
const normalizeBrokerPushOnMerge = (value: string | null | undefined): boolean => {
  const v = String(value || '').trim().toLowerCase();
  return !(v === '0' || v === 'false' || v === 'off' || v === 'no');
};
// The shared task queue is a newline-separated list (one task per line). Reading consumes
// nothing; consuming is done explicitly by takeNextBrokerTask().
const readBrokerTaskQueue = (): string[] => {
  try {
    const raw = localStorage.getItem(BROKER_TASK_QUEUE_KEY) || '';
    return raw.split('\n').map((s) => s.trim()).filter(Boolean);
  } catch { return []; }
};
const writeBrokerTaskQueue = (tasks: string[]): void => {
  try { localStorage.setItem(BROKER_TASK_QUEUE_KEY, tasks.join('\n')); } catch { /* ignore */ }
};
// Pop the first queued task (FIFO) and persist the rest. Returns null when empty.
const takeNextBrokerTask = (): string | null => {
  const tasks = readBrokerTaskQueue();
  if (!tasks.length) return null;
  const [next, ...rest] = tasks;
  writeBrokerTaskQueue(rest);
  try { window.dispatchEvent(new CustomEvent('octo-broker-task-queue-change')); } catch { /* ignore */ }
  return next;
};

const normalizeBrokerReviewMode = (value: string | null | undefined): BrokerReviewMode => {
  const v = String(value || '').trim();
  return v === 'off' || v === 'light' || v === 'normal' || v === 'careful' || v === 'very_careful'
    ? v
    : 'careful';
};

const normalizeBrokerBrowserReview = (value: string | null | undefined): boolean => {
  const v = String(value || '').trim().toLowerCase();
  return !(v === '0' || v === 'false' || v === 'off' || v === 'no');
};

// Continuous mode is OPT-IN (default off): when on, the harness does NOT stop after a
// successful merge — it loops back to developing and keeps building → merging → building.
const normalizeBrokerContinuous = (value: string | null | undefined): boolean => {
  const v = String(value || '').trim().toLowerCase();
  return v === '1' || v === 'true' || v === 'on' || v === 'yes';
};

