const normalizeVersion = (v: string) => String(v || '').trim().replace(/^v/i, '');

const clampNumber = (n: unknown, min: number, max: number, fallback: number) => {
  const v = typeof n === 'number' ? n : parseFloat(String(n ?? '').trim());
  if (!Number.isFinite(v)) return fallback;
  return Math.min(max, Math.max(min, v));
};

const openExternalUrl = async (url: string) => {
  const u = String(url || '').trim();
  if (!u) return;
  try {
    // Use Tauri shell plugin directly (no JS plugin dependency).
    await invoke('plugin:shell|open', { path: u });
    return;
  } catch {
    // Fallback for dev/web preview.
  }
  try {
    window.open(u, '_blank', 'noopener,noreferrer');
  } catch {
    // ignore
  }
};


const isImagePath = (filePath: string): boolean => {
  const p = String(filePath || '').toLowerCase();
  const ext = p.split('.').pop() || '';
  if (!ext || ext === p) return false;
  return ext === 'png'
    || ext === 'jpg'
    || ext === 'jpeg'
    || ext === 'gif'
    || ext === 'webp'
    || ext === 'bmp'
    || ext === 'svg'
    || ext === 'ico'
    || ext === 'avif'
    || ext === 'tif'
    || ext === 'tiff';
};

const isVideoPath = (filePath: string): boolean => {
  const ext = String(filePath || '').toLowerCase().split('.').pop() || '';
  return ext === 'mp4' || ext === 'webm' || ext === 'mov' || ext === 'avi' || ext === 'mkv' || ext === 'ogv';
};

const isAudioPath = (filePath: string): boolean => {
  const ext = String(filePath || '').toLowerCase().split('.').pop() || '';
  return ext === 'mp3' || ext === 'wav' || ext === 'ogg' || ext === 'flac' || ext === 'aac' || ext === 'm4a' || ext === 'wma' || ext === 'opus';
};

const guessAudioMime = (filePath: string): string => {
  const ext = String(filePath || '').toLowerCase().split('.').pop() || '';
  const map: Record<string, string> = { mp3: 'audio/mpeg', wav: 'audio/wav', ogg: 'audio/ogg', flac: 'audio/flac', aac: 'audio/aac', m4a: 'audio/mp4', wma: 'audio/x-ms-wma', opus: 'audio/opus' };
  return map[ext] || 'audio/mpeg';
};

const isPdfPath = (filePath: string): boolean => {
  const ext = String(filePath || '').toLowerCase().split('.').pop() || '';
  return ext === 'pdf';
};

const highlightSearchMatch = (text: string, query: string): React.ReactNode => {
  if (!query.trim()) return text;
  const parts = query.trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return text;
  const escaped = parts.map((p) => p.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
  const pattern = new RegExp(`(${escaped.join('|')})`, 'gi');
  const segments = text.split(pattern);
  return segments.map((seg, i) => {
    if (!seg) return null;
    if (i % 2 === 1) {
      return (
        <mark
          key={i}
          style={{
            background: 'rgba(255, 213, 79, 0.45)',
            color: 'inherit',
            padding: 0,
            borderRadius: 2,
          }}
        >
          {seg}
        </mark>
      );
    }
    return <React.Fragment key={i}>{seg}</React.Fragment>;
  });
};

