const guessVideoMime = (filePath: string): string => {
  const ext = String(filePath || '').toLowerCase().split('.').pop() || '';
  const map: Record<string, string> = { mp4: 'video/mp4', webm: 'video/webm', mov: 'video/quicktime', avi: 'video/x-msvideo', mkv: 'video/x-matroska', ogv: 'video/ogg' };
  return map[ext] || 'video/mp4';
};

const guessImageMime = (filePath: string): string => {
  const p = String(filePath || '').toLowerCase();
  const ext = p.split('.').pop() || '';
  if (ext === 'png') return 'image/png';
  if (ext === 'jpg' || ext === 'jpeg') return 'image/jpeg';
  if (ext === 'gif') return 'image/gif';
  if (ext === 'webp') return 'image/webp';
  if (ext === 'bmp') return 'image/bmp';
  if (ext === 'svg') return 'image/svg+xml';
  if (ext === 'ico') return 'image/x-icon';
  if (ext === 'avif') return 'image/avif';
  if (ext === 'tif' || ext === 'tiff') return 'image/tiff';
  return 'application/octet-stream';
};


const coerceLinearSizes = (sizes: number[], count: number) => {
  const out = Array.from({ length: count }, (_, i) => (Number.isFinite(sizes?.[i]) ? Number(sizes[i]) : 0));
  const minSize = 5;
  for (let i = 0; i < out.length; i++) out[i] = Math.max(minSize, out[i] || 0);
  const sum = out.reduce((a, b) => a + b, 0) || 1;
  return out.map((n) => (n / sum) * 100);
};

const defaultGridSizes = (count: number, maxPerRow: number) => {
  const colCount = Math.max(1, maxPerRow);
  const rowCount = Math.max(1, Math.ceil(Math.max(1, count) / colCount));
  const out: number[] = [];
  for (let row = 0; row < rowCount; row++) {
    const colsInRow = Math.min(colCount, count - row * colCount);
    const w = colsInRow > 0 ? 100 / colsInRow : 100;
    for (let col = 0; col < colsInRow; col++) out.push(w);
  }
  return out.length === count ? out : Array(count).fill(100 / Math.max(1, count));
};

const coerceGridSizes = (sizes: number[], count: number, maxPerRow: number) => {
  const colCount = Math.max(1, maxPerRow);
  const rowCount = Math.max(1, Math.ceil(Math.max(1, count) / colCount));
  const out = Array.from({ length: count }, (_, i) => (Number.isFinite(sizes?.[i]) ? Number(sizes[i]) : 0));
  const minSize = 8;
  for (let row = 0; row < rowCount; row++) {
    const start = row * colCount;
    const colsInRow = Math.min(colCount, count - start);
    const slice = out.slice(start, start + colsInRow);
    for (let i = 0; i < slice.length; i++) slice[i] = Math.max(minSize, slice[i] || 0);
    const sum = slice.reduce((a, b) => a + b, 0) || 1;
    const normalized = slice.map((n) => (n / sum) * 100);
    for (let i = 0; i < colsInRow; i++) out[start + i] = normalized[i];
  }
  return out;
};

function parseTerminalGitStatus(raw: string, workDir: string): TerminalGitStatus {
  let branch = '';
  let ahead = 0;
  let behind = 0;
  let staged = 0;
  let unstaged = 0;
  let untracked = 0;
  let conflicted = 0;
  for (const line of raw.split('\n')) {
    if (line.startsWith('# branch.head ')) {
      branch = line.slice(14).trim();
    } else if (line.startsWith('# branch.ab ')) {
      const m = line.match(/\+(\d+)\s+-(\d+)/);
      if (m) {
        ahead = parseInt(m[1], 10) || 0;
        behind = parseInt(m[2], 10) || 0;
      }
    } else if (line.startsWith('1 ') || line.startsWith('2 ')) {
      const xy = line.split(' ')[1] || '';
      if (xy[0] && xy[0] !== '.') staged += 1;
      if (xy[1] && xy[1] !== '.') unstaged += 1;
    } else if (line.startsWith('? ')) {
      untracked += 1;
    } else if (line.startsWith('u ')) {
      conflicted += 1;
    }
  }
  return {
    branch: branch || 'HEAD',
    ahead,
    behind,
    staged,
    unstaged,
    untracked,
    conflicted,
    repo: true,
    workDir,
    updatedAt: Date.now(),
  };
}

function getPathTail(path: string): string {
  const normalized = (path || '').trim().replace(/[\\/]+$/g, '');
  if (!normalized) return '';
  return normalized.split(/[\\/]/).filter(Boolean).pop() || normalized;
}

function quoteForShell(value: string): string {
  return `'${String(value || '').replace(/'/g, `'\\''`)}'`;
}

function windowsPathToWslPath(value: string): string {
  const path = String(value || '').replace(/\\/g, '/');
  const match = /^([a-zA-Z]):\/(.*)$/.exec(path);
  if (!match) return path;
  return `/mnt/${match[1].toLowerCase()}/${match[2]}`;
}

function quotePathForTerminal(value: string, terminal?: { shellType?: ShellType }): string {
  const path = terminal?.shellType === 'wsl' ? windowsPathToWslPath(value) : value;
  if (terminal?.shellType === 'cmd') {
    return `"${String(path || '').replace(/"/g, '""')}"`;
  }
  return quoteForShell(path);
}

