const OPEN_FILES_STATE_KEY = 'octo-open-files-state-v1';

type OpenFilesStateV1 = {
  v: 1;
  perProject: Record<string, { paths: string[]; active: string | null }>;
};

const loadOpenFilesState = async (): Promise<OpenFilesStateV1> => {
  try {
    const raw = await kvGet(OPEN_FILES_STATE_KEY);
    if (!raw) return { v: 1, perProject: {} };
    const parsed = JSON.parse(raw) as Partial<OpenFilesStateV1> | null;
    if (!parsed || parsed.v !== 1 || typeof parsed.perProject !== 'object' || !parsed.perProject) {
      return { v: 1, perProject: {} };
    }
    return { v: 1, perProject: parsed.perProject as OpenFilesStateV1['perProject'] };
  } catch {
    return { v: 1, perProject: {} };
  }
};

const MAX_LOADED_EDITOR_TABS = 42;
const MAX_LOADED_EDITOR_BYTES = 32 * 1024 * 1024;
const TARGET_LOADED_EDITOR_BYTES = 22 * 1024 * 1024;
const MAX_OPEN_TABS = 60;

const getOpenFileBytes = (file: OpenFile): number => (typeof file.content === 'string' ? file.content.length : 0);
const isOpenFileLoaded = (file: OpenFile): boolean => file.loaded !== false;
const getOpenFileLineCount = (path: string, content: string): number | undefined =>
  isLineCountEligiblePath(path) ? countTextLines(content) : undefined;

function compactOpenFilesForMemory(openFiles: OpenFile[], keepPaths: Set<string>): OpenFile[] {
  let loadedCount = 0;
  let totalBytes = 0;
  for (const file of openFiles) {
    if (!isOpenFileLoaded(file)) continue;
    loadedCount += 1;
    totalBytes += getOpenFileBytes(file);
  }
  if (loadedCount <= MAX_LOADED_EDITOR_TABS && totalBytes <= MAX_LOADED_EDITOR_BYTES) return openFiles;

  let changed = false;
  const next = [...openFiles];
  for (let i = 0; i < next.length; i += 1) {
    const file = next[i];
    if (!file) continue;
    if (keepPaths.has(file.path)) continue;
    if (file.modified) continue;
    if (!isOpenFileLoaded(file)) continue;
    // office 에디터는 content=''를 신규 빈 문서로 오인해 저장 시 원본을 파괴하므로 축출 제외
    if (file.kind === 'xlsx' || file.kind === 'docx' || file.kind === 'pptx') continue;
    if (loadedCount <= MAX_LOADED_EDITOR_TABS && totalBytes <= TARGET_LOADED_EDITOR_BYTES) break;

    totalBytes = Math.max(0, totalBytes - getOpenFileBytes(file));
    loadedCount -= 1;
    next[i] = { ...file, content: '', loaded: false };
    changed = true;
  }
  return changed ? next : openFiles;
}

function appendOpenFileWithTabCap(openFiles: OpenFile[], nextFile: OpenFile, keepPaths: Set<string>): {
  files: OpenFile[];
  accepted: boolean;
  evictedPath?: string;
} {
  if (openFiles.some((f) => f.path === nextFile.path)) {
    return { files: openFiles, accepted: true };
  }
  if (openFiles.length < MAX_OPEN_TABS) {
    return { files: [...openFiles, nextFile], accepted: true };
  }
  const removableIndex = openFiles.findIndex((f) => !keepPaths.has(f.path) && !f.modified);
  if (removableIndex < 0) {
    return { files: openFiles, accepted: false };
  }
  const next = [...openFiles];
  const [evicted] = next.splice(removableIndex, 1);
  next.push(nextFile);
  return { files: next, accepted: true, evictedPath: evicted?.path };
}

function createTerminal(
  name: string = 'Shell 1',
  cliType: 'shell' | 'claude' | 'codex' | 'cursor' | 'opencode' | 'kimi' | 'gemini' | 'ollama' | 'qwen' | 'pi' | 'reasonix' | 'bbarit' | 'bbarit-oss' | 'gajae' = 'shell',
  autoAccept: boolean = false,
  startupMode?: 'normal' | 'auto-accept' | 'bypass-permissions' | 'auto-edit' | 'full-auto' | 'yolo',
  shellType?: ShellType
): TerminalInstance {
  return {
    id: Date.now().toString() + Math.random().toString(36).substr(2, 9),
    name,
    cliType,
    shellType,
    autoAccept,
    startupMode,
    telegramChatId: '',
    discordChannelId: '',
  };
}

// 터미널에서 마지막으로 실행한 명령의 앞 10자 배지 — 터미널 상단 오버레이와
// 하단 pill 공용. 새 명령 커밋 시 배지만 자체 재렌더(useSyncExternalStore).
function TerminalLastCmd({ terminalId, overlay, big }: { terminalId: string; overlay?: boolean; big?: boolean }) {
  useSyncExternalStore(subscribeLastCommands, lastCommandsVersion);
  const cmd = lastCommandOf(terminalId);
  if (!cmd) return null;
  const max = big ? 26 : 10;
  const badge = (
    <span className={big ? 'terminal-last-cmd-big' : 'terminal-last-cmd'} title={cmd}>
      {cmd.length > max ? `${cmd.slice(0, max)}…` : cmd}
    </span>
  );
  return overlay ? <div className="terminal-last-cmd-overlay">{badge}</div> : badge;
}

// Main-grid terminal slot. While the terminal is popped out into its own OS
// window the xterm unmounts here and a notice takes its place; the popout owns
// the (single-consumer) PTY output stream. On re-attach the slot mounts with
// isRestored so XTerminal's restored-PTY probe replays the backend buffer.
function MainGridTerminal({ detached, onShowWindow, onReattach, ...termProps }: {
  detached: boolean;
  onShowWindow: () => void;
  onReattach: () => void;
} & React.ComponentProps<typeof XTerminal>) {
  const wasDetachedRef = useRef(false);
  if (detached) wasDetachedRef.current = true;
  if (!detached) {
    return <XTerminal {...termProps} isRestored={wasDetachedRef.current || termProps.isRestored} />;
  }
  return (
    <div className="terminal-detached-notice">
      <LucideIcons.PictureInPicture2 size={28} />
      <div className="terminal-detached-text">Popped out to a separate window</div>
      <div className="terminal-detached-actions">
        <button type="button" onClick={onShowWindow}>Show Window</button>
        <button type="button" onClick={onReattach}>Bring Back</button>
      </div>
    </div>
  );
}

